<script>document.addEventListener('DOMContentLoaded',()=>{const sidebar=document.getElementById('sidebar'),backdrop=document.getElementById('sidebarBackdrop');document.getElementById('openSidebar')?.addEventListener('click',()=>{sidebar?.classList.add('open');backdrop?.classList.remove('hidden')});backdrop?.addEventListener('click',()=>{sidebar?.classList.remove('open');backdrop.classList.add('hidden')});document.getElementById('type')?.addEventListener('change',event=>{document.getElementById('status').value='';event.target.form.submit()});document.getElementById('printReport')?.addEventListener('click',()=>window.print());document.getElementById('exportCsv')?.addEventListener('click',()=>{const table=document.getElementById('executiveReportTable');if(!table)return;const csv=[...table.rows].map(row=>[...row.cells].map(cell=>'"'+cell.innerText.replaceAll('"','""').replaceAll('\n',' · ')+'"').join(',')).join('\n'),blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='{{ $reportType }}_executive_reports_page_{{ $reportRows->currentPage() }}.csv';link.click();URL.revokeObjectURL(url)});});</script>
<script>document.addEventListener('DOMContentLoaded',()=>{const button=document.getElementById('userDropdownBtn'),menu=document.getElementById('userDropdownMenu');if(!button||!menu)return;button.addEventListener('click',event=>{event.stopPropagation();const open=menu.classList.toggle('show');button.setAttribute('aria-expanded',open?'true':'false')});document.addEventListener('click',event=>{if(!button.contains(event.target)&&!menu.contains(event.target)){menu.classList.remove('show');button.setAttribute('aria-expanded','false')}})});</script>
